metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books online"
        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing and buying books" {
            webStore = container "Web Store" "The web application where customers browse the catalogue and place orders" "Java"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Java"
        }

        customer -> webStore "Browses the catalogue and places orders" "HTTPS"
        webStore -> orderProcessor "Submits orders for processing" "gRPC"
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Customer and the Bookshop system" {
            include *
            autoLayout
        }
    }
}
